'use strict';
const content=document.querySelector('#content');
const cases={healthy:{name:'Healthy leaf',score:96.2,description:'This example represents a leaf without visible disease symptoms.',symptoms:'Even green coloration, an intact leaf surface, and no obvious spots or lesions.',next:'Continue routine observation. A healthy-looking leaf does not rule out early or hidden disease.'},early:{name:'Early blight',score:91.7,description:'This example represents a tomato leaf with an early blight pattern.',symptoms:'Brown spots with concentric rings, often accompanied by yellowing around the affected area.',next:'Inspect additional leaves and ask a local agricultural extension specialist to confirm the cause before choosing treatment.'},septoria:{name:'Septoria leaf spot',score:89.4,description:'This example represents a tomato leaf with a leaf spot pattern.',symptoms:'Small circular spots with pale centers and darker edges; symptoms can overlap with other conditions.',next:'Document affected leaves and seek local expert confirmation. A photo alone cannot establish the cause.'}};
const state={file:null,url:null,sample:null,result:null,busy:false,error:'',generation:0};
const icon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/></svg>';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function intro(k,title,desc,tag='TOMATO · PILOT CROP'){return `<div class="intro"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div><span class="tag">${tag}</span></div>`;}
function scanner(){content.innerHTML=intro('Observe. Understand. Act early.','A closer look at crop health.','Start with a leaf image. Explore the signs that deserve attention.')+`<div class="notice"><span aria-hidden="true">ⓘ</span><div><strong>Demo mode.</strong> Sample results are illustrative. A trained model is not connected, so uploads will not receive a disease diagnosis.</div></div><div class="scanner-grid"><section class="panel"><div class="panel-top"><h2><span class="step">01</span> Your leaf image</h2><span class="subtle">INPUT</span></div><div class="upload-inner"><label class="field-label">Selected crop</label><div class="crop-select"><span class="crop-badge" aria-hidden="true">✳</span> Tomato <small>Solanum lycopersicum</small></div><input class="file-input" id="file-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Choose a leaf image"><div class="dropzone" id="dropzone"></div><div id="upload-error" class="inline-error" role="alert"></div><button class="primary-btn" id="analyze" disabled>Check leaf image <span aria-hidden="true">↗</span></button><p class="privacy">Images stay in your browser. Nothing is uploaded.</p></div></section><section class="panel result" aria-label="Screening result"><div class="panel-top"><h2><span class="step">02</span> Screening result</h2><span class="subtle">OUTPUT</span></div><div class="result-body" id="result" aria-live="polite"></div></section></div><div class="below-grid"><section class="samples"><h2>No image handy?</h2><p>Explore a preset result. These are interface demos, not predictions.</p><div class="sample-grid"><button class="sample-btn" data-sample="healthy"><i class="sample-color"></i><span>Healthy leaf ↗</span><small>DEMO CASE 01</small></button><button class="sample-btn" data-sample="early"><i class="sample-color blight"></i><span>Early blight ↗</span><small>DEMO CASE 02</small></button><button class="sample-btn" data-sample="septoria"><i class="sample-color spot"></i><span>Leaf spot ↗</span><small>DEMO CASE 03</small></button></div></section><aside class="tips"><h2>Make every detail count.</h2><ul><li>Capture one leaf against a simple background.</li><li>Use natural light and keep the leaf in focus.</li><li>Include the whole leaf, especially affected areas.</li></ul></aside></div>`;
document.querySelector('#file-input').addEventListener('change',e=>{if(e.target.files[0])loadFile(e.target.files[0]);});
const dz=document.querySelector('#dropzone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('dragover');});dz.addEventListener('dragleave',()=>dz.classList.remove('dragover'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('dragover');if(e.dataTransfer.files.length!==1){showError('Please choose one image at a time.');return;}loadFile(e.dataTransfer.files[0]);});
document.querySelector('#analyze').addEventListener('click',analyze);document.querySelectorAll('[data-sample]').forEach(b=>b.addEventListener('click',()=>selectSample(b.dataset.sample)));renderInput();renderResult();}
function showError(message){state.error=message;const el=document.querySelector('#upload-error');if(el)el.textContent=message;}
function clearImage(){state.generation++;if(state.url)URL.revokeObjectURL(state.url);Object.assign(state,{file:null,url:null,sample:null,result:null,busy:false,error:''});const inp=document.querySelector('#file-input');if(inp)inp.value='';}
function renderInput(){const dz=document.querySelector('#dropzone');if(!dz)return;dz.innerHTML=state.url?`<div class="image-wrap"><img src="${state.url}" alt="Selected leaf image"><div class="file-row"><span>${escapeHTML(state.file.name)} · ${(state.file.size/1024).toFixed(0)} KB</span><button class="text-btn" id="remove">Remove</button></div></div>`:state.sample?`<div class="sample-staged"><div class="scan-icon" aria-hidden="true">⌗</div><strong>${cases[state.sample].name}</strong><p>Preset demonstration · No leaf image is being classified.</p><button class="browse" id="browse">Use your own image</button></div>`:`<div><div class="upload-symbol">${icon}</div><strong>Drop your leaf image here</strong><p>JPG, PNG or WebP · Up to 10 MB</p><button class="browse" id="browse">Browse files</button></div>`;
document.querySelector('#browse')?.addEventListener('click',()=>document.querySelector('#file-input').click());document.querySelector('#remove')?.addEventListener('click',()=>{clearImage();renderInput();renderResult();});const b=document.querySelector('#analyze');b.disabled=state.busy||(!state.file&&!state.sample);b.textContent=state.busy?'Checking image…':state.sample?'Show sample result ↗':'Check leaf image ↗';showError(state.error);}
async function loadFile(file){clearImage();renderInput();renderResult();if(!['image/jpeg','image/png','image/webp'].includes(file.type)){showError('Choose a JPG, PNG or WebP image.');return;}if(file.size>10*1024*1024){showError('This image is too large. Choose an image under 10 MB.');return;}const generation=state.generation;const url=URL.createObjectURL(file);const img=new Image();img.src=url;try{await img.decode();if(generation!==state.generation){URL.revokeObjectURL(url);return;}if(img.naturalWidth<128||img.naturalHeight<128)throw Error('Use an image at least 128 × 128 pixels so leaf details are visible.');if(img.naturalWidth*img.naturalHeight>40000000)throw Error('Please resize this image below 40 megapixels.');state.file={name:file.name,size:file.size,width:img.naturalWidth,height:img.naturalHeight};state.url=url;renderInput();}catch(e){URL.revokeObjectURL(url);if(generation===state.generation)showError(e.message.startsWith('Use ')||e.message.startsWith('Please ')?e.message:'This file could not be opened as an image. Try another file.');}}
function selectSample(key){if(!Object.hasOwn(cases,key))throw Error('Unknown sample case.');clearImage();state.sample=key;if(location.hash!=='#scanner')location.hash='scanner';else scanner();return {selected:key,mode:'demo'};}
async function analyze(){if(state.busy||(!state.file&&!state.sample))return;state.busy=true;state.result=null;const generation=state.generation;renderInput();renderResult();await new Promise(r=>setTimeout(r,650));if(generation!==state.generation)return;state.busy=false;state.result=state.sample?{type:'sample',key:state.sample}:{type:'upload'};renderInput();renderResult();}
function renderResult(){const el=document.querySelector('#result');if(!el)return;if(state.busy){el.innerHTML='<div class="empty-result"><div class="spinner"></div><h3>Preparing your result</h3><p>Loading the selected demo or checking image readability.</p></div>';return;}if(!state.result){el.innerHTML='<div class="empty-result"><div class="scan-icon" aria-hidden="true">⌗</div><h3>A little insight starts here.</h3><p>Add a leaf image or choose a demo case to explore the screening flow.</p></div><div class="result-footer"><span>Image preview</span><span>Clear next steps</span></div>';return;}if(state.result.type==='upload'){el.innerHTML=`<span class="result-label">IMAGE CHECK COMPLETE</span><h3 class="diagnosis">Ready for a trained model.</h3><p class="result-desc">Your image is readable. Disease classification is unavailable in this prototype.</p><div class="result-detail"><strong>Image details</strong><p>${state.file.width} × ${state.file.height} pixels · ${(state.file.size/1024).toFixed(0)} KB</p><p>This check does not verify that the image contains a tomato leaf.</p></div><div class="result-detail" style="margin-top:12px"><strong>What happens next?</strong><p>Connect a validated model to obtain real predictions. For now, try a sample below to explore the result format.</p></div>`;return;}
const c=cases[state.result.key];el.innerHTML=`<span class="result-label">ILLUSTRATIVE SAMPLE · NOT A DIAGNOSIS</span><h3 class="diagnosis">${c.name}</h3><p class="result-desc">${c.description}</p><div class="confidence-row"><span>Example confidence · simulated</span><b>${c.score}%</b></div><div class="bar"><i style="width:${c.score}%"></i></div><div class="result-detail"><strong>Signs to look for</strong><p>${c.symptoms}</p></div><div class="result-detail" style="margin-top:12px"><strong>A thoughtful next step</strong><p>${c.next}</p></div><button id="download" class="secondary-btn">↓ Download demo report</button>`;document.querySelector('#download').addEventListener('click',download);}
function download(){if(state.result?.type!=='sample')return;const c=cases[state.result.key];const report={project:'LeafLens',mode:'illustrative-demo',disclaimer:'Preset result only. No model inference was performed. Not a diagnosis.',crop:'Tomato',exampleClass:c.name,simulatedConfidence:c.score,symptoms:c.symptoms,nextStep:c.next,createdAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='leaflens-demo-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo report downloaded.');}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.hidden=false;setTimeout(()=>el.hidden=true,3000);}
function library(){content.innerHTML=intro('Know the visible signs','The leaf reference library.','A focused starting point for the tomato pilot.')+`<div class="notice">Reference descriptions help explain the demo. Similar symptoms can have different causes; expert confirmation is needed before treatment.</div><div class="cards">${Object.entries(cases).map(([key,c],i)=>`<article class="panel library-card"><span class="number">TOMATO / 0${i+1}</span><h2>${c.name}</h2><p>${c.description.replace('This example represents','A reference for')}</p><dl><dt>Visible signs</dt><dd>${c.symptoms}</dd><dt>Next step</dt><dd>${c.next}</dd></dl><button class="secondary-btn" data-case="${key}">Explore demo result ↗</button></article>`).join('')}<article class="panel library-card"><span class="number">SCOPE / NEXT PHASE</span><h2>Pest detection</h2><p>Planned extension</p><dl><dt>Why it is separate</dt><dd>Disease symptoms, insect damage, and environmental stress may look alike. Pest detection needs its own labeled and validated examples.</dd><dt>Current coverage</dt><dd>No pest model or pest predictions are included in this prototype.</dd></dl></article></div>`;document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>selectSample(b.dataset.case)));}
function evaluation(){content.innerHTML=intro('Evidence before confidence','Measure what matters.','An evaluation workspace for the next stage of the project.','MODEL NOT TRAINED')+`<div class="notice"><span>ⓘ</span><div><strong>No measured results yet.</strong> Demo confidence values are preset UI examples. They are not accuracy scores or evidence of model performance.</div></div><div class="metrics">${['Accuracy','Precision','Recall','F1-score'].map(m=>`<div class="panel metric"><p>${m}</p><strong>—</strong><small>Awaiting held-out evaluation</small></div>`).join('')}</div><section class="panel"><div class="panel-top"><h2>Model comparison</h2><span class="tag">PLANNED</span></div><div class="table-wrap"><table><thead><tr><th>Model</th><th>Approach</th><th>Status</th><th>Macro F1</th></tr></thead><tbody><tr><td><strong>Baseline CNN</strong></td><td>Train from scratch</td><td>Not trained</td><td>—</td></tr><tr><td><strong>MobileNetV2</strong></td><td>Transfer learning</td><td>Not trained</td><td>—</td></tr></tbody></table></div></section><div class="cards" style="margin-top:23px"><section class="panel prose"><h2>A repeatable evaluation</h2><ol><li>Collect and verify labeled tomato leaf images.</li><li>Split data into 70% training, 15% validation, and 15% testing, grouped by original leaf or source.</li><li>Apply augmentation only to training images.</li><li>Compare both models on the same untouched test set.</li><li>Report per-class results and a confusion matrix, then check separate field photographs.</li></ol></section><section class="panel prose"><h2>Project success criteria</h2><p><strong>Initial target: ≥90% test accuracy.</strong> This is a goal, not an achieved result. Class imbalance and field conditions must also be considered.</p><p><strong>Recall:</strong> how many affected leaves are detected. <strong>Precision:</strong> how often a disease prediction is correct. <strong>Macro F1:</strong> the average class F1 score, giving each class equal weight.</p><p>Choose the uncertainty threshold using validation data. Record inference time and test-set size alongside every published score.</p></section></div>`;}
function project(){content.innerHTML=intro('Agriculture & environmental sustainability','A small project. A clear purpose.','Crop disease awareness through leaf images.','SDG 2 · ZERO HUNGER')+`<section class="panel prose"><h2>Project definition</h2><p>LeafLens is a mini-project prototype for crop disease screening using computer vision. The pilot focuses on tomato leaves and demonstrates healthy, early blight, and Septoria leaf spot result screens. Its intended purpose is to support early awareness and timely expert intervention.</p><p>The problem statement supplied for this project references <strong>SIH26131 – Software</strong>. This prototype does not claim official affiliation or validation.</p><div class="workflow"><div><span class="number">01 / INPUT</span><strong>Capture a leaf</strong><p>Choose one clear JPG, PNG or WebP image.</p></div><div><span class="number">02 / PREPARE</span><strong>Validate the image</strong><p>Check type, size and image readability locally.</p></div><div><span class="number">03 / MODEL</span><strong>Classify with evidence</strong><p>Future work: train and validate a CNN and MobileNetV2.</p></div><div><span class="number">04 / OUTPUT</span><strong>Support early action</strong><p>Present class, calibrated confidence and appropriate next steps.</p></div></div></section><div class="cards" style="margin-top:23px"><section class="panel prose"><h2>Available in this prototype</h2><ul><li>Drag-and-drop image input and local preview</li><li>File validation and readable image details</li><li>Three explicitly labeled demonstration cases</li><li>Downloadable demo reports</li><li>Disease references and model evaluation plan</li></ul></section><section class="panel prose"><h2>Before real-world use</h2><ul><li>Source a suitable labeled dataset and verify its license.</li><li>Train, compare and evaluate both models.</li><li>Add out-of-scope and low-confidence rejection.</li><li>Validate on photographs from actual farms.</li><li>Review guidance with an agricultural specialist.</li></ul></section></div>`;}
const pages={scanner,library,evaluation,project};
function route(){let key=location.hash.slice(1)||'scanner';if(!Object.hasOwn(pages,key))key='scanner';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===key);if(a.dataset.page===key){a.setAttribute('aria-current','page');document.querySelector('#breadcrumb').textContent=a.textContent.trim();}else a.removeAttribute('aria-current');});pages[key]();window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'stage_leaf_demo',description:'Select an illustrative tomato leaf case in the scanner. Does not classify an image or run a model.',inputSchema:{type:'object',properties:{case:{type:'string',enum:Object.keys(cases)}},required:['case'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!Object.hasOwn(cases,input.case))throw Error('Provide a supported case.');const result=selectSample(input.case);route();return result;}})).catch(()=>{});}catch{}}
